window.VD=window.VD||{};window.VD["audi/tt-8n"]={"tt-8n-activate-counter-backlight-on-contact":"<p><strong>Purpose:</strong> Enables the gauge faces and counter needles to be illuminated as soon as the ignition is switched on (after 2002).   </p>\n<p><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>“.<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – Add <strong>+1</strong> (for gauges) and/or <strong>+2</strong> (for needles) (so <strong>+3</strong> for both) for the first digit (<strong>?xxxx</strong>)</p>","tt-8n-automatic-door-locks":"<p><strong>Purpose:</strong> to set automatic door locking from 15km/h.  </p>\n<p><strong>Proceed :</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>35 – Central lock </strong></strong>” .<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p><em>Add +32 to the base value</em></p>","tt-8n-change-odb-language":"<p><strong>Purpose:</strong> to change the language of messages on the driver information system display.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>” then click on<strong>“Channel 04</strong>”.<br/><br/><strong>5</strong> – Modify value: <strong>langCode</strong></p>\n<p>00001 – German<br/>00002 – English<br/>00003 – French<br/>00004 – Italian<br/>00005 – Spanish<br/>00006 – Portuguese</p>","tt-8n-cruise-control-activation-retrofit":"<p><strong>Purpose:</strong> to activate the speed governor after retrofitting.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>01 – Motor</strong> “.</p>\n<p><strong>4</strong> – Click on “<strong>Access – 11</strong>” then enter the code “<strong><em><strong>11463</strong></em></strong>”  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur2-6871f13e.webp\"/></figure>","tt-8n-deactivate-windshield-washer-indicator":"<p><strong>Purpose</strong>: to deactivate the windshield washer indicator on the ODB (on-board computer). (Model after 2000)</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on<strong>“17 – Instruments</strong>” . 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>” .</p>\n<p><strong>5</strong> –  <em>The first two digits of the code (<strong>??</strong>xxx) are used to modify the Instrument module options. To remove the ice-washer indicator, subtract <strong>04</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/InstrumentCoding-0794d7c9.webp\"/></figure>\n<p>In the example above, the initial coding (with washer indicator) is: <strong>07232</strong></p>\n<p>To remove the windscreen washer indicator, simply recode as follows: <strong>03232</strong> <em>(07 – 04 = 05)</em></p>\n<p>To activate the ice washer indicator: +04</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglace-edc83d4f.webp\"/></figure>","tt-8n-delete-belt-alarm":"<p><strong>Purpose</strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>17 – Instruments</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> –  <em>The first two digits of the code (<strong>??</strong>xxxx) are used to modify the Instrument module options. To suppress the belt alarm, subtract <strong>2</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/InstrumentCoding-0794d7c9.webp\"/></figure>\n<p>In the above example, the initial coding (with belt alarm) is: <strong>07232</strong></p>\n<p>To delete the belt alarm, simply recode as follows: <strong>05232</strong> <em>(07 – 02 = 05)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","tt-8n-door-lock-unlock-confirmation-horn":"<p><strong>Purpose:</strong> To set confirmation of door locking/unlocking with beep (horn).  </p>\n<p><strong>Proceed :</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>35 – Central lock </strong></strong>” .<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p><em>Add +1024 to base value</em></p>","tt-8n-door-lock-unlock-confirmation-turn-signals":"<p><strong>Purpose: </strong>activates confirmation of vehicle locking/unlocking with turn signals.  </p>\n<p><strong>Procedure:</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>35 – Central lock </strong></strong>” .<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p>Add <strong>+512</strong> (for flasher on lock) and/or <strong>+4096</strong> (for flasher on unlock) to base value</p>","tt-8n-opening-closing-windows-with-remote-control":"<p><strong>Purpose:</strong> to activate closing and opening of windows and sunroof with remote control.  </p>\n<p>Press and hold the buttons on the remote control or use the lock cylinder to open and close the windows and sunroof. <br/><br/><br/><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>3</strong> – Click <strong>“Select</strong>,” then click <strong><strong>“35 – Central Locking”</strong></strong> .<br/><br/><strong>4 – </strong>Click on <strong>“Coding – 07</strong>” </p>\n<p>Add <strong>+64</strong> to base value</p>","tt-8n-outdoor-temperature-display-on-odb":"<p><strong>Purpose:</strong> to add an external temperature display to the on-board computer. (After 2002)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – Add <strong>+1</strong> to the penultimate digit<strong>(xxx?x</strong>)</p>","tt-8n-show-hidden-menu-climatronic":"<p><strong>Purpose: Displays </strong>the Climatronic hidden menu.  </p>\n<p><strong>Display the instantaneous digital speed? It’s possible! </strong>  You don’t need to use your VCDS VAG-COM cable for this tutorial.  </p>\n<p><strong>What is it used for?</strong></p>\n<p>In the hidden Audi Climatronic menu, you can easily access secret diagnostic readings such as battery voltage, vehicle speed, engine RPM, sensor readings, system DTCs, and much more.</p>\n<h3>Hidden single-zone Audi Climatronic menu procedure</h3>\n<p>To display some of the car’s operating parameters on the air-conditioning display:</p>\n<ol>\n<li>Simultaneously press the air recirculation button and the upward ventilation button.</li>\n<li>The display shows “1C” (channel 1 is the default).</li>\n<li>Use the temperature change knob to select the desired function. Press “+” to access the upper channel and “-” to access the lower channel. </li>\n<li>For example, for real-time engine oil temperature, you need to display channel 51 (51C on the screen).</li>\n<li>Confirm the function by pressing the air recirculation button.</li>\n<li>The selected channel’s information is then displayed on the climate control screen.</li>\n</ol>\n<figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatisation_1-5803fa4a.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatisation_2-f3440ecb.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatisation_3-e0877cf3.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatisation_4-c24dbc07.webp\"/></figure>\n</figure>\n<h3>List of Hidden Channels in the Menus</h3>\n<figure><table><tbody><tr><td>1</td><td>System error</td></tr><tr><td>2</td><td>Virtual sensor value</td></tr><tr><td>3</td><td>Inside console sensor value</td></tr><tr><td>4</td><td>Outside temperature value – water tank sensor</td></tr><tr><td>5</td><td>Outside temperature value – bumper sensor</td></tr><tr><td>6</td><td>Lower supply sensor value</td></tr><tr><td>7</td><td>Front air sensor value</td></tr><tr><td>8</td><td>Display check</td></tr><tr><td>9</td><td>Digital value of temperature valve return potentiometer</td></tr><tr><td>10</td><td>Digital temperature valve setpoint</td></tr><tr><td>11</td><td>Digital value of air-conditioning valve return potentiometer</td></tr><tr><td>12</td><td>Digital air conditioning valve setpoint</td></tr><tr><td>13</td><td>Digital value of foot valve/defrost return potentiometer</td></tr><tr><td>14</td><td>Digital foot valve/defrost setpoint</td></tr><tr><td>15</td><td>Digital value of supply air damper return potentiometer</td></tr><tr><td>16</td><td>Digital supply air damper setpoint</td></tr><tr><td>17</td><td>Speed in km/h</td></tr><tr><td>18</td><td>Ventilation voltage value (Volts)</td></tr><tr><td>19</td><td>Ventilation voltage setpoint (Volts)</td></tr><tr><td>20</td><td>Compressor voltage value (Volts)</td></tr><tr><td>21</td><td>Number of very low voltage events (non-volatile)</td></tr><tr><td>22</td><td>High-pressure switch status</td></tr><tr><td>23</td><td>Number of high-pressure events (volatile)</td></tr><tr><td>24</td><td>Number of high-pressure events (non-volatile)</td></tr><tr><td>25</td><td>A/D value Kick-Down switch</td></tr><tr><td>26</td><td>A/D value warm indicator light</td></tr><tr><td>27</td><td>Engine speed</td></tr><tr><td>28</td><td>Compressor speed</td></tr><tr><td>29</td><td>Encoding</td></tr><tr><td>30</td><td>Software Version</td></tr><tr><td>31</td><td>Software index</td></tr><tr><td>32</td><td>Error counter potentiometer temperature valve</td></tr><tr><td>33</td><td>Meter errors potentiometer air conditioning valve</td></tr><tr><td>34</td><td>Meter errors potentiometer feet/defrost valve</td></tr><tr><td>35</td><td>Error meter potentiometer supply air damper</td></tr><tr><td>36</td><td>Cold stop temperature valve</td></tr><tr><td>37</td><td>Hot stop temperature valve</td></tr><tr><td>38</td><td>Air conditioning damper stop closed</td></tr><tr><td>39</td><td>Air conditioning damper stop open</td></tr><tr><td>40</td><td>Foot valve/defrost stop</td></tr><tr><td>41</td><td>Foot stop foot valve/defrost</td></tr><tr><td>42</td><td>Supply air damper stop open</td></tr><tr><td>43</td><td>Supply air damper stop closed</td></tr><tr><td>44</td><td>Rolling cycle counter</td></tr><tr><td>45</td><td>Calculated indoor temperature (Ninc)</td></tr><tr><td>46</td><td>Filtered outdoor temperature (°C)</td></tr><tr><td>47</td><td>Unfiltered outdoor temperature (°C)</td></tr><tr><td>48</td><td>ECOR</td></tr><tr><td>49</td><td>Coolant temperature</td></tr><tr><td>50</td><td>Stopping time in minutes</td></tr><tr><td>51</td><td>Engine oil temperature in °C</td></tr><tr><td>52</td><td>Compressor stop conditions</td></tr><tr><td>53</td><td>Display active electrical outputs: compressor, room air valve, water valve</td></tr><tr><td>54</td><td>Control indication number</td></tr><tr><td>55</td><td>Outside temperature in °C</td></tr><tr><td>56</td><td>Virtual indoor sensor °C</td></tr><tr><td>57</td><td>Indoor console sensor °C</td></tr><tr><td>58</td><td>Water tank temperature °C</td></tr><tr><td>59</td><td>Bumper temperature °C</td></tr><tr><td>60</td><td>Lower supply sensor temperature</td></tr><tr><td>61</td><td>Temperature of front air sensor</td></tr><tr><td>62</td><td>Solar intensity W/m-1</td></tr><tr><td>63</td><td>Filtered solar intensity W/m-1</td></tr><tr><td>64</td><td>Delta ventilation increase</td></tr><tr><td>65</td><td>Delta transition air conditioning dampers</td></tr><tr><td>66</td><td>Cadence time /1.6 sec</td></tr><tr><td>67</td><td>Cold start correction</td></tr><tr><td>68</td><td>Maximum setpoint P and I components</td></tr><tr><td>69</td><td>Blower sensor value feet (cnts)</td></tr><tr><td>70</td><td>Foot blow sensor setpoint (cnts)</td></tr><tr><td>71</td><td>Difference (Epsilon)</td></tr><tr><td>72</td><td>Share (+ heating / – cooling)</td></tr></tbody></table></figure>"};
